function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw dog
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50 * Math.sin(t), H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 + 50 * Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 50 * Math.sin(t) - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 50 * Math.sin(t) + 20, H/2 + 70);
  ctx.stroke();

  // draw tail
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t), H/2 + 70);
  ctx.lineTo(W/2 + 50 * Math.sin(t) + 30 * Math.cos(t), H/2 + 90);
  ctx.stroke();

  // draw ear
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t) - 15, H/2 + 10);
  ctx.lineTo(W/2 + 50 * Math.sin(t) - 25, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.sin(t) + 15, H/2 + 10);
  ctx.lineTo(W/2 + 50 * Math.sin(t) + 25, H/2 - 10);
  ctx.stroke();

  ctx.restore();
}
